function validate(input) {
  const [{ Employees = [], Logs = [] }] = input;
  const ids = new Set(), sessions = new Set();
  for (const [id, needed] of Employees) {
    if (id === null || needed === null) return 'employee_id and needed_hours are required.';
    if (ids.has(id)) return `employee_id ${id} appears twice in Employees.`;
    ids.add(id);
    if (needed < 0) return 'needed_hours cannot be negative.';
  }
  const stamp = /^2022-10-(0[1-9]|[12]\d|3[01]) ([01]\d|2[0-3]):[0-5]\d:[0-5]\d$/;
  for (const [id, start, end] of Logs) {
    if (id === null || start === null || end === null) return 'Logs values are required.';
    if (!ids.has(id)) return `Logs names employee ${id}, who is not in Employees.`;
    if (!stamp.test(start) || !stamp.test(end)) return 'Times must be October 2022 datetimes written YYYY-MM-DD HH:MM:SS.';
    if (start >= end) return `A session of employee ${id} does not end after it starts.`;
    const key = `${id}|${start}|${end}`;
    if (sessions.has(key)) return `Employee ${id} has the same session twice.`;
    sessions.add(key);
  }
  return null;
}

