function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const at = ms => new Date(ms).toISOString().slice(0, 19).replace('T', ' ');
  const october = Date.UTC(2022, 9, 1), november = Date.UTC(2022, 10, 1);
  const Employees = [], Logs = [], seen = new Set();
  // Session lengths sit on and just past whole minutes, so rounding up and summing per session matter.
  const minutes = size === 'small' ? [0, 19, 29, 59, 60, 119, 179] : [5, 29, 59, 60, 90, 119, 179, 239, 299, 479, 599];
  const seconds = [0, 1, 30, 59];
  const session = id => {
    const length = (minutes[pick(minutes.length)] * 60 + seconds[pick(seconds.length)]) * 1000 || 1000;
    // Start on the hour or a few seconds past it; late starts run past midnight.
    const start = october + pick(30) * 86400000 + pick(24) * 3600000 + pick(3) * 1000;
    if (start + length >= november) return;
    const row = [id, at(start), at(start + length)], key = row.join('|');
    if (seen.has(key)) return;
    seen.add(key);
    Logs.push(row);
  };
  if (size === 'small') {
    const people = pick(5);
    for (let id = 1; id <= people; id++) Employees.push([id, pick(5)]);
    const rows = people ? pick(9) : 0;
    for (let i = 0; i < rows; i++) session(1 + pick(people));
  } else {
    // About 6 sessions per employee averaging under 3 hours; needed hours straddle that.
    for (let id = 1; id <= 300; id++) Employees.push([id, pick(30)]);
    for (let tries = 0; Logs.length < 1800 && tries < 5000; tries++) session(1 + pick(300));
  }
  return [{ Employees, Logs }];
}
